-- Cadastro persistente de clientes e migração única da base legada.
CREATE TABLE `customers` (
  `id` CHAR(36) NOT NULL,
  `code` VARCHAR(20) NOT NULL,
  `legal_name` VARCHAR(180) NOT NULL,
  `segment` VARCHAR(80) NULL,
  `seller` VARCHAR(120) NULL,
  `representative` VARCHAR(120) NULL,
  `active` BOOLEAN NOT NULL DEFAULT true,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL,
  UNIQUE INDEX `customers_code_key` (`code`),
  INDEX `customers_active_idx` (`active`),
  INDEX `customers_legal_name_idx` (`legal_name`),
  INDEX `customers_segment_idx` (`segment`),
  INDEX `customers_seller_idx` (`seller`),
  INDEX `customers_representative_idx` (`representative`),
  PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;








